    return 64 * x**3 + 100 * x**2 + 322 * x - 486

values = {}
for x in range(1, 11):
    val = Q(x)
    values[x] = val

print("Q(x) values for x=1 to 10:")
for x, val in values.items():
    print(f"Q({x}) = {val}")

# Check ratios between consecutive values
print("\nConsecutive Ratios Q(x+1)/Q(x):")
for x in range(1, 10):
    try:
        ratio = values[x+1] / values[x]
        print(f"Q({x+1})/Q({x}) = {ratio:.4f}")
    except ZeroDivisionError:
        print(f"Q({x}) = 0, ratio undefined.")

